// Appends Hair Removal ids 451-475 (25 questions)
import { readFileSync, writeFileSync } from 'fs'
import { fileURLToPath } from 'url'
import { join, dirname } from 'path'
const __dirname = dirname(fileURLToPath(import.meta.url))
const FILE = join(__dirname, '../src/esthi-questions.js')

const hrT=`"Hair Removal"`, hrTes=`"Depilación"`, hrPt=`"Hair Removal"`, hrPtes=`"Depilación"`

function fmt(q) {
  return `  { id: ${q.id}, topic: ${hrT}, topic_es: ${hrTes}, psi_topic: ${hrPt}, psi_topic_es: ${hrPtes}, question: ${JSON.stringify(q.question)}, question_es: ${JSON.stringify(q.question_es)}, options: ${JSON.stringify(q.options)}, options_es: ${JSON.stringify(q.options_es)}, correct: ${q.correct}, explanation: ${JSON.stringify(q.explanation)} },`
}

const HR = [
  { id: 451, question: "What is the primary difference between the hard wax and soft (strip) wax methods of hair removal?", question_es: "¿Cuál es la principal diferencia entre los métodos de depilación con cera dura y cera blanda (en tiras)?", options: ["Hard wax is applied thickly, hardens on its own, and is removed without a cloth strip by lifting an edge and pulling against the direction of hair growth — making it gentler on sensitive areas; soft wax is applied thinly and removed using a cloth or paper strip", "Hard wax requires a cloth strip for removal while soft wax never requires any strip or cloth at all", "Hard wax can only be used on the legs while soft wax can only be used on facial areas", "There is no meaningful difference between the two — the names refer only to the texture of the container the wax is stored in"], options_es: ["La cera dura se aplica en una capa gruesa, se endurece por sí sola y se retira sin una tira de tela levantando un borde y tirando en contra de la dirección del crecimiento del vello — lo que la hace más suave en áreas sensibles; la cera blanda se aplica en una capa fina y se retira con una tira de tela o papel", "La cera dura requiere una tira de tela para su remoción mientras que la cera blanda nunca requiere ninguna tira o tela", "La cera dura solo se puede usar en las piernas mientras que la cera blanda solo se puede usar en áreas faciales", "No hay ninguna diferencia significativa entre las dos — los nombres se refieren solo a la textura del recipiente donde se almacena la cera"], correct: 0, explanation: "Hard wax is applied in a thicker layer, cools and hardens on the skin, and is removed by hand without a strip — gripping the hair at the root and typically causing less trauma to delicate skin, making it popular for sensitive areas like the face and bikini area. Soft (strip) wax is applied in a thin layer and removed using a cloth or paper strip pulled against the direction of hair growth, and is commonly used for larger areas like the legs and arms." },
  { id: 452, question: "Before applying wax to a client's skin, the esthetician should test the wax temperature because:", question_es: "Antes de aplicar cera a la piel de un cliente, el esteticista debe probar la temperatura de la cera porque:", options: ["Wax that is too hot can cause burns or significant skin damage, while wax that is too cool will not adhere properly or remove hair effectively — testing helps confirm it is at a safe, effective temperature before application", "Testing wax temperature is solely a matter of personal preference with no real safety implications", "Wax temperature has no effect on either client safety or treatment effectiveness", "Wax should always be applied as hot as possible to guarantee the most thorough hair removal"], options_es: ["La cera demasiado caliente puede causar quemaduras o daño significativo a la piel, mientras que la cera demasiado fría no se adherirá adecuadamente ni eliminará el vello de manera efectiva — probarla ayuda a confirmar que está a una temperatura segura y eficaz antes de la aplicación", "Probar la temperatura de la cera es únicamente una cuestión de preferencia personal sin implicaciones reales de seguridad", "La temperatura de la cera no tiene ningún efecto ni en la seguridad del cliente ni en la eficacia del tratamiento", "La cera siempre debe aplicarse lo más caliente posible para garantizar la depilación más completa"], correct: 0, explanation: "Wax that is too hot poses a serious burn risk, especially on sensitive areas, while wax that is too cool will not spread evenly, adhere to the hair, or release cleanly from the skin — reducing effectiveness and increasing discomfort. Testing the wax (such as on the esthetician's own wrist or a small inconspicuous area) before application to the client is an essential safety and quality step." },
  { id: 453, question: "Which best describes why the skin should be cleansed and thoroughly dried before applying wax for hair removal?", question_es: "¿Cuál describe mejor por qué la piel debe limpiarse y secarse completamente antes de aplicar cera para la depilación?", options: ["Removing oils, lotions, sweat, and moisture helps the wax adhere properly to the hair and skin, supporting more effective hair removal and reducing the likelihood of the wax slipping, smearing, or failing to grip the hair", "Cleansing and drying the skin has no effect on how well wax adheres or performs", "Skipping cleansing actually improves wax adhesion by leaving a helpful protective layer of natural oils", "Cleansing is only necessary for clients with visibly oily skin and can be skipped for all other clients"], options_es: ["Eliminar aceites, lociones, sudor y humedad ayuda a que la cera se adhiera correctamente al vello y a la piel, favoreciendo una depilación más efectiva y reduciendo la probabilidad de que la cera se deslice, se corra o no agarre el vello", "Limpiar y secar la piel no tiene ningún efecto en qué tan bien se adhiere o funciona la cera", "Omitir la limpieza en realidad mejora la adherencia de la cera al dejar una capa protectora útil de aceites naturales", "La limpieza solo es necesaria para clientes con piel visiblemente grasa y se puede omitir para todos los demás clientes"], correct: 0, explanation: "Oils, lotions, sweat, and surface moisture create a barrier between the wax and the hair/skin, reducing the wax's ability to grip the hair effectively. Properly cleansing and drying the area beforehand allows the wax to adhere as intended, supporting more effective and even hair removal and reducing the chances of slipping, smearing, or incomplete results." },
  { id: 454, question: "Which best describes the proper technique for removing a soft (strip) wax application from the skin?", question_es: "¿Cuál describe mejor la técnica adecuada para retirar una aplicación de cera blanda (en tiras) de la piel?", options: ["Holding the skin taut with one hand, and quickly pulling the strip back against the direction of hair growth, close and parallel to the skin, in one swift motion", "Slowly peeling the strip upward and away from the skin at a 90-degree angle to minimize discomfort", "Pulling the strip in the same direction as hair growth to make the process gentler on the skin", "Leaving the strip in place for an extended period before any attempt at removal, regardless of product instructions"], options_es: ["Sosteniendo la piel tensa con una mano y tirando rápidamente de la tira hacia atrás en contra de la dirección del crecimiento del vello, cerca y paralela a la piel, en un movimiento rápido", "Despegando lentamente la tira hacia arriba y alejándola de la piel en un ángulo de 90 grados para minimizar la incomodidad", "Tirando de la tira en la misma dirección que el crecimiento del vello para hacer el proceso más suave para la piel", "Dejando la tira en su lugar durante un período prolongado antes de cualquier intento de remoción, sin importar las instrucciones del producto"], correct: 0, explanation: "Proper strip removal technique involves holding the skin taut to reduce discomfort and minimize trauma, then quickly pulling the strip back against the direction of hair growth, keeping it close and parallel (low) to the skin's surface. This technique helps remove hair efficiently from the root, reduces breakage, and tends to be less painful than slow removal or pulling at an angle away from the skin." },
  { id: 455, question: "Why should an esthetician avoid applying wax to skin that has any visible cuts, abrasions, active rashes, or signs of sunburn?", question_es: "¿Por qué un esteticista debe evitar aplicar cera en piel que tenga cortes visibles, abrasiones, erupciones activas o signos de quemadura solar?", options: ["Waxing over compromised skin can worsen the existing condition, cause significant pain, increase the risk of infection or further injury, and remove healthy skin along with the hair in already-fragile areas", "Compromised skin always responds better to waxing than healthy, intact skin", "These conditions have no effect on how skin responds to the waxing process", "Cuts, abrasions, and rashes always heal more quickly when wax is applied directly over them"], options_es: ["Encerar sobre piel comprometida puede empeorar la condición existente, causar dolor significativo, aumentar el riesgo de infección o lesión adicional, y eliminar piel sana junto con el vello en áreas ya frágiles", "La piel comprometida siempre responde mejor a la cera que la piel sana e intacta", "Estas condiciones no tienen ningún efecto en cómo responde la piel al proceso de depilación con cera", "Los cortes, abrasiones y erupciones siempre cicatrizan más rápido cuando se les aplica cera directamente"], correct: 0, explanation: "Skin that is already compromised — through cuts, abrasions, active rashes, or sunburn — is more fragile and reactive. Applying wax to these areas (and the subsequent removal process) can cause significant pain, further damage healthy tissue, increase infection risk, and worsen the existing condition. These are recognized contraindications for waxing on the affected area, and the esthetician should avoid that area or postpone the service." },
  { id: 456, question: "A client mentions they are using a topical acne medication containing benzoyl peroxide on the area to be waxed. What is the most relevant consideration for the esthetician?", question_es: "Un cliente menciona que está usando un medicamento tópico contra el acné que contiene peróxido de benzoilo en el área que se va a depilar con cera. ¿Cuál es la consideración más relevante para el esteticista?", options: ["Topical acne medications can make the skin more sensitive, dry, and prone to irritation or lifting during waxing, so the esthetician should ask about frequency of use and consider postponing the service or using a gentler method", "Topical acne medications have no effect whatsoever on how skin responds to waxing", "The esthetician should recommend the client double their usual application of the medication immediately before the appointment", "Acne medications make skin more resistant to irritation, so more aggressive waxing technique can safely be used"], options_es: ["Los medicamentos tópicos contra el acné pueden hacer que la piel sea más sensible, seca y propensa a la irritación o al levantamiento durante la depilación con cera, por lo que el esteticista debe preguntar sobre la frecuencia de uso y considerar posponer el servicio o usar un método más suave", "Los medicamentos tópicos contra el acné no tienen ningún efecto en cómo responde la piel a la depilación con cera", "El esteticista debe recomendar que el cliente duplique su aplicación habitual del medicamento inmediatamente antes de la cita", "Los medicamentos contra el acné hacen que la piel sea más resistente a la irritación, por lo que se puede usar con seguridad una técnica de depilación más agresiva"], correct: 0, explanation: "Topical acne treatments such as benzoyl peroxide can dry out and sensitize the skin, increasing the risk of irritation, redness, or lifting when wax is applied and removed. Asking about current product use and frequency helps the esthetician decide whether to postpone the service, recommend a waiting period, or select a gentler hair removal method for that area." },
  { id: 457, question: "What is the primary purpose of applying a soothing, post-treatment product (such as an aloe-based gel or calming lotion) immediately after a waxing service?", question_es: "¿Cuál es el propósito principal de aplicar un producto calmante posterior al tratamiento (como un gel a base de aloe o una loción calmante) inmediatamente después de un servicio de depilación con cera?", options: ["To help soothe the skin, reduce redness and inflammation, and provide comfort following the mechanical stress of hair removal on the treated area", "To permanently prevent any future hair growth in the treated area", "To replace the need for the client to follow any further aftercare instructions at home", "To restore the wax's adhesive properties so it can be reused on the same client later"], options_es: ["Ayudar a calmar la piel, reducir el enrojecimiento y la inflamación, y proporcionar alivio después del estrés mecánico de la depilación en el área tratada", "Prevenir permanentemente cualquier futuro crecimiento de vello en el área tratada", "Reemplazar la necesidad de que el cliente siga cualquier instrucción adicional de cuidado posterior en casa", "Restaurar las propiedades adhesivas de la cera para que pueda reutilizarse en el mismo cliente más tarde"], correct: 0, explanation: "Waxing involves mechanical stress on the skin and hair follicles, often resulting in temporary redness, sensitivity, or mild inflammation. A soothing post-treatment product helps calm the skin and provide comfort right after the service — but it is just one part of a complete aftercare routine, and does not replace the need for the client to follow additional at-home guidance, nor does it have any effect on future hair growth." },
  { id: 458, question: "A client asks why their esthetician recommends gently exfoliating the skin a few days before (not immediately before) a scheduled waxing appointment. The most accurate explanation is that:", question_es: "Un cliente pregunta por qué su esteticista recomienda exfoliar suavemente la piel unos días antes (no inmediatamente antes) de una cita de depilación con cera programada. La explicación más precisa es que:", options: ["Gentle exfoliation performed a few days in advance can help remove dead skin cells that might otherwise trap hairs beneath the surface, supporting a smoother wax application and result, while avoiding exfoliating too close to the appointment, which could leave skin more sensitive", "Exfoliation has no relationship to how the skin or hair responds to waxing at any point in time", "Exfoliating immediately before a wax always produces the smoothest possible results with no downsides", "Exfoliation is recommended solely to make the service take less time for the esthetician"], options_es: ["La exfoliación suave realizada unos días antes puede ayudar a eliminar las células muertas de la piel que de otro modo podrían atrapar los vellos debajo de la superficie, favoreciendo una aplicación y un resultado de cera más uniformes, mientras se evita exfoliar demasiado cerca de la cita, lo que podría dejar la piel más sensible", "La exfoliación no tiene ninguna relación con cómo responde la piel o el vello a la depilación con cera en ningún momento", "Exfoliar inmediatamente antes de una cera siempre produce los resultados más suaves posibles sin ninguna desventaja", "La exfoliación se recomienda únicamente para que el servicio le tome menos tiempo al esteticista"], correct: 0, explanation: "Gentle exfoliation performed a few days before a waxing appointment can help clear away built-up dead skin cells that might otherwise trap hairs beneath the surface, contributing to a smoother result and potentially reducing the risk of ingrown hairs. However, exfoliating too close to the appointment (or too aggressively) can leave skin more sensitive and reactive, which is why timing matters in this recommendation." },
  { id: 459, question: "Which of the following is most appropriate for an esthetician to communicate to a first-time waxing client about what to expect during and immediately after the service?", question_es: "¿Cuál de las siguientes es lo más apropiado para que un esteticista le comunique a un cliente que se depila con cera por primera vez sobre qué esperar durante e inmediatamente después del servicio?", options: ["Explaining honestly that some discomfort is common during hair removal, that mild redness or sensitivity afterward is normal and typically temporary, and what steps the client can take if irritation persists or worsens", "Promising the client that the procedure will be completely painless and that no redness or sensitivity of any kind will occur", "Avoiding any explanation so the client is fully surprised by what they experience", "Telling the client that any discomfort experienced means something has gone seriously wrong with the service"], options_es: ["Explicar honestamente que cierta incomodidad es común durante la depilación, que el enrojecimiento o la sensibilidad leves después son normales y generalmente temporales, y qué pasos puede seguir el cliente si la irritación persiste o empeora", "Prometerle al cliente que el procedimiento será completamente indoloro y que no ocurrirá ningún tipo de enrojecimiento o sensibilidad", "Evitar cualquier explicación para que el cliente se sorprenda por completo con lo que experimenta", "Decirle al cliente que cualquier incomodidad experimentada significa que algo ha salido gravemente mal con el servicio"], correct: 0, explanation: "Honest, realistic communication helps first-time clients feel prepared and supported. Explaining that some discomfort during hair removal and mild, temporary redness or sensitivity afterward are common — while also describing when something would warrant follow-up — builds trust and reduces anxiety, in contrast to overpromising a painless experience, withholding information, or causing unnecessary alarm over expected, normal responses." },
  { id: 460, question: "A client asks the esthetician to perform a waxing service on an area where they have a suspicious-looking mole that has reportedly changed in appearance recently. The most appropriate response is to:", question_es: "Un cliente le pide al esteticista que realice un servicio de depilación con cera en un área donde tiene un lunar de apariencia sospechosa que según se informa ha cambiado de apariencia recientemente", options: ["Avoid waxing directly over or immediately around the area in question, recommend the client have it evaluated by a dermatologist, and proceed only with unaffected areas as appropriate", "Proceed with waxing directly over the mole exactly as requested, since hair removal procedures cannot affect a mole in any way", "Refuse to perform any service anywhere on the client's body because of the presence of one concerning mole", "Apply extra wax directly to the mole in an attempt to remove it along with the surrounding hair"], options_es: ["Evitar la depilación con cera directamente sobre o inmediatamente alrededor del área en cuestión, recomendar que el cliente lo haga evaluar por un dermatólogo, y proceder solo con las áreas no afectadas según corresponda", "Proceder con la depilación con cera directamente sobre el lunar exactamente como se solicitó, ya que los procedimientos de depilación no pueden afectar a un lunar de ninguna manera", "Negarse a realizar cualquier servicio en cualquier parte del cuerpo del cliente debido a la presencia de un lunar preocupante", "Aplicar cera adicional directamente sobre el lunar en un intento de eliminarlo junto con el vello circundante"], correct: 0, explanation: "A mole described as changing in size, shape, or color carries warning signs that fall outside the scope of esthetic evaluation or treatment. Waxing directly over or immediately around such an area could cause trauma, irritation, or bleeding, and risks masking or complicating future medical evaluation. The appropriate response is to avoid that specific area, recommend prompt evaluation by a dermatologist, and continue providing appropriate service to unaffected areas." },
  { id: 461, question: "Threading, as a method of hair removal, primarily works by:", question_es: "El hilo, como método de depilación, funciona principalmente mediante:", options: ["Using a twisted strand of thread that is rolled across the skin's surface to catch and lift multiple hairs at the follicle level, removing them from the root without the use of chemicals or heated products", "Applying a chemical solution that dissolves the hair shaft at the surface of the skin", "Using a heated wire to cut through the hair shaft just above the skin's surface", "Using suction-based devices that pull hairs out using vacuum pressure alone"], options_es: ["Usar una hebra de hilo retorcida que se enrolla sobre la superficie de la piel para atrapar y levantar múltiples vellos a nivel del folículo, eliminándolos desde la raíz sin el uso de químicos o productos calentados", "Aplicar una solución química que disuelve el tallo del vello en la superficie de la piel", "Usar un alambre caliente para cortar el tallo del vello justo encima de la superficie de la piel", "Usar dispositivos basados en succión que extraen los vellos únicamente mediante presión de vacío"], correct: 0, explanation: "Threading uses a twisted length of cotton or polyester thread that is rolled along the surface of the skin, catching multiple hairs in the twists and lifting them out from the follicle. It is a temporary hair removal method that does not involve chemicals, heat, or adhesives, and is commonly used for shaping eyebrows and removing fine facial hair." },
  { id: 462, question: "Which best describes a key advantage of threading compared to waxing for clients with very sensitive skin or certain skin conditions?", question_es: "¿Cuál describe mejor una ventaja clave del hilo en comparación con la cera para clientes con piel muy sensible o ciertas condiciones de la piel?", options: ["Threading does not involve applying any product or adhesive directly to the skin's surface, which can make it a gentler option for some clients with reactive or product-sensitive skin, though it still requires proper technique to avoid irritation", "Threading is always completely painless for every client regardless of skin sensitivity", "Threading permanently eliminates hair growth after a single treatment, unlike waxing", "Threading requires no training or technique and can be performed safely by anyone without practice"], options_es: ["El hilo no implica aplicar ningún producto o adhesivo directamente sobre la superficie de la piel, lo que puede convertirlo en una opción más suave para algunos clientes con piel reactiva o sensible a los productos, aunque todavía requiere una técnica adecuada para evitar la irritación", "El hilo siempre es completamente indoloro para todos los clientes sin importar la sensibilidad de su piel", "El hilo elimina permanentemente el crecimiento del vello después de un solo tratamiento, a diferencia de la cera", "El hilo no requiere ninguna capacitación o técnica y puede realizarse de forma segura por cualquier persona sin práctica"], correct: 0, explanation: "Because threading does not involve applying wax, adhesives, or chemical products to the skin, it can be a more suitable option for some clients who are sensitive or reactive to those products. However, it is still a manual hair removal technique that involves tension and lifting hairs from the follicle, requires skillful technique to perform comfortably and effectively, and — like other temporary methods — does not produce permanent results." },
  { id: 463, question: "Tweezing is generally considered most appropriate for:", question_es: "El uso de pinzas generalmente se considera más apropiado para:", options: ["Removing small numbers of stray or individual hairs in precise areas, such as cleaning up brow shape between larger services, due to its precision but relatively slow pace for larger areas", "Removing hair from large areas such as the legs or back as the primary method due to its speed and efficiency", "Permanently destroying the hair follicle so that no further growth ever occurs in that location", "Replacing the need for any consultation about the client's hair removal goals or preferences"], options_es: ["Eliminar pequeñas cantidades de vellos sueltos o individuales en áreas precisas, como perfeccionar la forma de las cejas entre servicios más grandes, debido a su precisión pero ritmo relativamente lento para áreas grandes", "Eliminar el vello de áreas grandes como las piernas o la espalda como método principal debido a su rapidez y eficiencia", "Destruir permanentemente el folículo piloso para que no vuelva a ocurrir ningún crecimiento en esa ubicación", "Reemplazar la necesidad de cualquier consulta sobre los objetivos o preferencias de depilación del cliente"], correct: 0, explanation: "Tweezing involves removing individual hairs one at a time by gripping them at the base and pulling them from the follicle. Its precision makes it well suited for detailed work — such as shaping eyebrows or cleaning up small stray hairs between larger services — but its slow, one-at-a-time nature makes it impractical as a primary method for larger areas. Like other mechanical methods, it is temporary and does not destroy the follicle." },
  { id: 464, question: "Which best explains why depilatory creams (chemical hair removal products) require a patch test before full application, especially for a new client?", question_es: "¿Cuál explica mejor por qué las cremas depilatorias (productos químicos de depilación) requieren una prueba de parche antes de la aplicación completa, especialmente para un nuevo cliente?", options: ["These products contain chemicals that break down the protein structure of the hair shaft, and the same chemicals can also irritate or burn skin in sensitive individuals, so a patch test helps identify a reaction risk before broader application", "Depilatory creams never cause any type of reaction in any client, making patch testing purely a formality with no real value", "Patch testing is required only to determine the exact shade of the product before use", "Patch testing eliminates the need to ask the client about any known allergies or skin sensitivities"], options_es: ["Estos productos contienen químicos que descomponen la estructura proteica del tallo del vello, y los mismos químicos también pueden irritar o quemar la piel en personas sensibles, por lo que una prueba de parche ayuda a identificar un riesgo de reacción antes de la aplicación más amplia", "Las cremas depilatorias nunca causan ningún tipo de reacción en ningún cliente, lo que hace que la prueba de parche sea puramente una formalidad sin ningún valor real", "La prueba de parche es necesaria únicamente para determinar el tono exacto del producto antes de su uso", "La prueba de parche elimina la necesidad de preguntar al cliente sobre cualquier alergia o sensibilidad de la piel conocida"], correct: 0, explanation: "Depilatory creams work by chemically breaking down the protein (keratin) structure of the hair shaft so it can be wiped away. Because these are reactive chemical formulations, they carry a real risk of causing irritation, burns, or allergic-type reactions in some individuals. A patch test on a small area, combined with reviewing the client's allergy and sensitivity history, helps reduce the risk of a more widespread adverse reaction during full application." },
  { id: 465, question: "A client asks why depilatory cream results last about the same amount of time as shaving, even though the cream is applied as a 'treatment' rather than using a razor. The most accurate explanation is:", question_es: "Un cliente pregunta por qué los resultados de la crema depilatoria duran aproximadamente lo mismo que el afeitado, aunque la crema se aplica como un 'tratamiento' en lugar de usar una navaja. La explicación más precisa es:", options: ["Both methods remove hair at or near the surface of the skin rather than from the root/follicle, so regrowth becomes noticeable on a similar general timeline for many individuals, though it can vary by person and area", "Depilatory creams always remove hair from the root in the same way as waxing, producing identical regrowth timelines to waxing rather than shaving", "Shaving and depilatory creams are functionally identical products with no difference in how they interact with the hair shaft", "Depilatory cream results always last significantly longer than any other temporary hair removal method available"], options_es: ["Ambos métodos eliminan el vello en o cerca de la superficie de la piel en lugar de desde la raíz/folículo, por lo que el recrecimiento se vuelve notable en una línea de tiempo general similar para muchas personas, aunque puede variar según la persona y el área", "Las cremas depilatorias siempre eliminan el vello desde la raíz de la misma manera que la cera, produciendo líneas de tiempo de recrecimiento idénticas a la cera en lugar del afeitado", "El afeitado y las cremas depilatorias son productos funcionalmente idénticos sin ninguna diferencia en cómo interactúan con el tallo del vello", "Los resultados de la crema depilatoria siempre duran significativamente más que cualquier otro método de depilación temporal disponible"], correct: 0, explanation: "Depilatory creams dissolve the visible hair shaft at or near the surface of the skin rather than removing the hair from the root/follicle, similar in that respect to shaving (which cuts the hair at the surface). Because the follicle and root remain intact with both methods, regrowth tends to become noticeable on a fairly similar general timeline — in contrast to root-based methods like waxing or threading, which can offer comparatively longer-lasting smoothness for many individuals." },
  { id: 466, question: "Which best describes an appropriate way for an esthetician to address a client who has a known allergy to a specific chemical commonly found in depilatory creams, but who specifically requests that method?", question_es: "¿Cuál describe mejor una manera apropiada para que un esteticista aborde a un cliente que tiene una alergia conocida a un químico específico comúnmente encontrado en las cremas depilatorias, pero que solicita específicamente ese método?", options: ["Explain the relevant risk clearly, decline to use a product containing the known allergen, and discuss alternative hair removal methods that may better suit the client's needs and safety", "Use the depilatory cream exactly as requested, since client preference always overrides any known allergy information", "Apply the product to a very small area only, assuming that a smaller amount cannot trigger any reaction", "Tell the client that depilatory creams cannot realistically cause allergic reactions in anyone"], options_es: ["Explicar claramente el riesgo relevante, negarse a usar un producto que contenga el alérgeno conocido, y discutir métodos alternativos de depilación que puedan adaptarse mejor a las necesidades y seguridad del cliente", "Usar la crema depilatoria exactamente como se solicitó, ya que la preferencia del cliente siempre anula cualquier información de alergia conocida", "Aplicar el producto solo en un área muy pequeña, asumiendo que una cantidad menor no puede desencadenar ninguna reacción", "Decirle al cliente que las cremas depilatorias no pueden causar realmente reacciones alérgicas en nadie"], correct: 0, explanation: "Knowingly using a product containing an allergen the client has identified poses a real safety risk, regardless of the client's preference for that method. The professional, ethical response is to clearly explain the concern, decline to use the specific product, and work with the client to find a suitable alternative — never proceeding with a known allergen 'in moderation' or dismissing the client's documented sensitivity." },
  { id: 467, question: "Sugaring, as a hair removal method, is most accurately described as:", question_es: "El azucarado, como método de depilación, se describe con mayor precisión como:", options: ["A technique using a paste typically made from natural ingredients such as sugar, water, and lemon juice, applied and removed in the direction of hair growth (often by hand, in a flicking motion) to lift hair from the follicle", "A permanent hair removal method that uses concentrated light energy to destroy the hair follicle", "A chemical process that dissolves the hair shaft at the surface of the skin using sugar-based acids", "A method that requires heated metal tools to be pressed directly against the hair shaft"], options_es: ["Una técnica que utiliza una pasta típicamente hecha de ingredientes naturales como azúcar, agua y jugo de limón, que se aplica y se retira en la dirección del crecimiento del vello (a menudo a mano, con un movimiento de sacudida) para levantar el vello del folículo", "Un método de depilación permanente que utiliza energía luminosa concentrada para destruir el folículo piloso", "Un proceso químico que disuelve el tallo del vello en la superficie de la piel usando ácidos a base de azúcar", "Un método que requiere herramientas de metal calentadas que se presionan directamente contra el tallo del vello"], correct: 0, explanation: "Sugaring uses a paste made from natural ingredients (commonly sugar, water, and lemon juice or similar acids) that is applied to the skin and removed — often by hand, in a flicking motion — in the direction of hair growth, lifting hair out from the follicle. This is sometimes considered a gentler alternative for some clients, as it tends to adhere primarily to the hair rather than strongly bonding to the skin's surface, though proper technique is still essential for safety and comfort." },
  { id: 468, question: "Which is an appropriate consideration for an esthetician when deciding whether sugaring is a suitable hair removal option for a particular client?", question_es: "¿Cuál es una consideración apropiada para un esteticista al decidir si el azucarado es una opción de depilación adecuada para un cliente en particular?", options: ["Reviewing the client's skin sensitivity, known allergies (including to any natural ingredients used in the paste), and the treatment area, since sugaring — while sometimes considered gentle — still involves direct contact and mechanical force on the skin and hair", "Assuming sugaring is automatically appropriate for every client and every area without any further consultation", "Assuming that, because the ingredients are natural, no allergic reactions or skin sensitivities are possible", "Skipping any discussion of the client's hair removal history or goals, since sugaring is identical to all other methods in every respect"], options_es: ["Revisar la sensibilidad de la piel del cliente, las alergias conocidas (incluso a cualquier ingrediente natural utilizado en la pasta) y el área de tratamiento, ya que el azucarado — aunque a veces se considera suave — todavía implica contacto directo y fuerza mecánica sobre la piel y el vello", "Asumir que el azucarado es automáticamente apropiado para cada cliente y cada área sin ninguna consulta adicional", "Asumir que, debido a que los ingredientes son naturales, no son posibles las reacciones alérgicas ni las sensibilidades de la piel", "Omitir cualquier discusión sobre el historial o los objetivos de depilación del cliente, ya que el azucarado es idéntico a todos los demás métodos en todos los aspectos"], correct: 0, explanation: "Even though sugaring paste is often made from natural ingredients and is sometimes perceived as gentle, 'natural' does not mean risk-free — clients can still be allergic or sensitive to specific components (such as citrus), and the technique still involves direct contact and mechanical force on the skin. A thorough consultation that considers the client's history, sensitivities, and the treatment area helps the esthetician determine whether sugaring (or another method) is the most suitable, safe choice." },
  { id: 469, question: "Which of the following best describes an appropriate scope-of-practice boundary for a licensed esthetician regarding laser or light-based permanent hair reduction services?", question_es: "¿Cuál de las siguientes describe mejor un límite apropiado del alcance de práctica para un esteticista licenciado con respecto a los servicios de reducción permanente del vello con láser o basados en luz?", options: ["An esthetician should only perform such procedures if permitted under their specific license and applicable regulations, with appropriate additional training and certification, and should refer clients to an appropriately licensed provider when the service falls outside their authorized scope", "Any esthetician may perform any laser or light-based hair removal procedure regardless of their license type or additional training", "Laser and light-based hair removal procedures are always completely outside any esthetician's scope under every possible regulatory framework", "Scope-of-practice rules for advanced devices are merely guidelines and can be disregarded if the esthetician feels confident in their own ability"], options_es: ["Un esteticista solo debe realizar tales procedimientos si está permitido según su licencia específica y las regulaciones aplicables, con la capacitación y certificación adicionales apropiadas, y debe derivar a los clientes a un proveedor con la licencia apropiada cuando el servicio esté fuera de su alcance autorizado", "Cualquier esteticista puede realizar cualquier procedimiento de depilación con láser o basado en luz sin importar su tipo de licencia o capacitación adicional", "Los procedimientos de depilación con láser y basados en luz siempre están completamente fuera del alcance de cualquier esteticista bajo todos los marcos regulatorios posibles", "Las reglas de alcance de práctica para dispositivos avanzados son simplemente pautas y pueden ignorarse si el esteticista se siente seguro de su propia capacidad"], correct: 0, explanation: "Whether and how an esthetician may perform laser or light-based hair reduction services depends on their specific license category, additional required training/certification, and the regulations of the jurisdiction in which they practice. The professionally and legally sound approach is to know and respect those specific boundaries, pursue any required additional credentials before offering such services, and refer clients to appropriately licensed providers when a requested service falls outside one's authorized scope." },
  { id: 470, question: "Which best describes why a thorough client consultation — including questions about skin tone, hair color, medical history, and medication use — is especially important before any light-based or laser hair reduction service?", question_es: "¿Cuál describe mejor por qué una consulta exhaustiva con el cliente — incluyendo preguntas sobre el tono de piel, el color del vello, el historial médico y el uso de medicamentos — es especialmente importante antes de cualquier servicio de reducción del vello basado en luz o láser?", options: ["These factors can significantly influence both the safety and effectiveness of light-based treatments, including the risk of burns, pigment changes, or other adverse effects, and certain medical conditions or medications can increase risk or serve as contraindications", "These factors are only relevant for clients receiving facial treatments and have no bearing on hair removal services", "Skin tone and hair color are purely cosmetic considerations with no connection to how the skin or hair responds to light-based treatments", "A consultation is only necessary if the client specifically requests one, since light-based treatments are equally safe and effective for everyone regardless of individual factors"], correct: 0, options_es: ["Estos factores pueden influir significativamente tanto en la seguridad como en la eficacia de los tratamientos basados en luz, incluido el riesgo de quemaduras, cambios de pigmento u otros efectos adversos, y ciertas condiciones médicas o medicamentos pueden aumentar el riesgo o servir como contraindicaciones", "Estos factores solo son relevantes para los clientes que reciben tratamientos faciales y no tienen relación con los servicios de depilación", "El tono de piel y el color del vello son consideraciones puramente cosméticas sin ninguna conexión con cómo responden la piel o el vello a los tratamientos basados en luz", "Una consulta solo es necesaria si el cliente la solicita específicamente, ya que los tratamientos basados en luz son igualmente seguros y eficaces para todos sin importar los factores individuales"], explanation: "Light-based and laser hair reduction technologies work by targeting pigment, which means skin tone and hair color directly affect both the safety profile (such as burn or pigment-change risk) and the likely effectiveness of the treatment. Certain medical conditions and medications (including photosensitizing drugs) can also increase risk or serve as contraindications. A thorough consultation gathers this essential information so an appropriately trained and licensed provider can determine whether — and how — to proceed safely." },
  { id: 471, question: "A client asks the esthetician to explain, in general terms, why some hair removal methods provide longer-lasting smoothness than others. An accurate, appropriately scoped explanation would describe:", question_es: "Un cliente le pide al esteticista que explique, en términos generales, por qué algunos métodos de depilación proporcionan una suavidad más duradera que otros. Una explicación precisa y con el alcance apropiado describiría:", options: ["Methods that remove the hair from the root/follicle (such as waxing, threading, tweezing, or sugaring) generally allow more time before regrowth becomes visible than methods that cut or dissolve the hair near the surface (such as shaving or depilatory creams), though individual results vary", "All hair removal methods produce results that last for exactly the same length of time with no meaningful variation between techniques", "Methods that cut the hair at the surface always last longer than any method that removes hair from the root", "The longevity of results depends solely on the brand of product used and not on the underlying method or technique"], options_es: ["Los métodos que eliminan el vello desde la raíz/folículo (como la cera, el hilo, las pinzas o el azucarado) generalmente permiten más tiempo antes de que el recrecimiento se vuelva visible que los métodos que cortan o disuelven el vello cerca de la superficie (como el afeitado o las cremas depilatorias), aunque los resultados individuales varían", "Todos los métodos de depilación producen resultados que duran exactamente el mismo tiempo sin ninguna variación significativa entre técnicas", "Los métodos que cortan el vello en la superficie siempre duran más que cualquier método que elimina el vello desde la raíz", "La duración de los resultados depende únicamente de la marca del producto utilizado y no del método o técnica subyacente"], correct: 0, explanation: "Root-based methods (waxing, threading, tweezing, sugaring) remove the entire hair from the follicle, generally requiring more time for new growth to become visible. Surface-level methods (shaving, depilatory creams) leave the root intact, so regrowth tends to become noticeable sooner. Explaining this general distinction in simple terms helps clients understand why their chosen method behaves the way it does — while acknowledging that individual factors (such as hair growth cycle and area treated) lead to natural variation in results." },
  { id: 472, question: "Which best describes an ingrown hair and why it can occur after certain hair removal methods?", question_es: "¿Cuál describe mejor un vello encarnado y por qué puede ocurrir después de ciertos métodos de depilación?", options: ["A hair that curls back or grows sideways into the skin rather than upward and out of the follicle, sometimes resulting in irritation, redness, or small bumps — this can happen when regrowing hair is blocked by dead skin cells or the hair's natural growth pattern after removal", "A type of permanent scar tissue that forms only as a result of laser-based hair removal procedures", "A normal, expected, and entirely painless part of the hair growth cycle that requires no attention or care", "A condition that occurs exclusively in clients who have never previously had any form of hair removal performed"], options_es: ["Un vello que se enrosca hacia atrás o crece de lado hacia la piel en lugar de hacia arriba y fuera del folículo, lo que a veces resulta en irritación, enrojecimiento o pequeños bultos — esto puede ocurrir cuando el vello que vuelve a crecer es bloqueado por células muertas de la piel o por el patrón natural de crecimiento del vello después de la remoción", "Un tipo de tejido cicatricial permanente que se forma únicamente como resultado de los procedimientos de depilación con láser", "Una parte normal, esperada y completamente indolora del ciclo de crecimiento del vello que no requiere ninguna atención o cuidado", "Una condición que ocurre exclusivamente en clientes que nunca antes se han sometido a ninguna forma de depilación"], correct: 0, explanation: "An ingrown hair occurs when a hair grows back into the skin instead of upward and out of the follicle opening — often because dead skin cells block the follicle or because of how the hair was cut or removed. This can lead to localized irritation, redness, small bumps, or discomfort. Gentle exfoliation between services and proper technique during hair removal can help reduce (though not entirely eliminate) the occurrence of ingrown hairs." },
  { id: 473, question: "What general aftercare guidance is commonly recommended to help reduce the likelihood of ingrown hairs and irritation following hair removal services such as waxing or sugaring?", question_es: "¿Qué orientación general de cuidado posterior se recomienda comúnmente para ayudar a reducir la probabilidad de vellos encarnados e irritación después de servicios de depilación como la cera o el azucarado?", options: ["Gently exfoliating the area a few days after the service (once any initial sensitivity has subsided), keeping the area clean, avoiding tight clothing that may cause friction, and using soothing, non-comedogenic products as appropriate", "Avoiding all contact with water on the treated area for at least two full weeks following the service", "Applying the strongest possible exfoliating product immediately after the service while the skin is still sensitive", "Wearing the tightest possible clothing over the treated area to help the skin heal more quickly"], options_es: ["Exfoliar suavemente el área unos días después del servicio (una vez que la sensibilidad inicial haya disminuido), mantener el área limpia, evitar ropa ajustada que pueda causar fricción, y usar productos calmantes y no comedogénicos según corresponda", "Evitar todo contacto con agua en el área tratada durante al menos dos semanas completas después del servicio", "Aplicar el producto exfoliante más fuerte posible inmediatamente después del servicio mientras la piel todavía está sensible", "Usar la ropa más ajustada posible sobre el área tratada para ayudar a que la piel sane más rápidamente"], correct: 0, explanation: "Reasonable aftercare to help minimize ingrown hairs and irritation typically includes waiting an appropriate amount of time before gently exfoliating, keeping the area clean, choosing looser clothing to reduce friction, and applying soothing, appropriate (non-comedogenic where relevant) products. This balanced approach supports healing and skin health — in contrast to extreme measures like avoiding water entirely, exfoliating too soon and aggressively, or wearing constrictive clothing." },
  { id: 474, question: "A client mentions they recently had a series of facial chemical peels and now wants to schedule a facial waxing service in the same area. The most appropriate response is to:", question_es: "Un cliente menciona que recientemente se sometió a una serie de peelings químicos faciales y ahora quiere programar un servicio de depilación con cera facial en la misma área. La respuesta más apropiada es:", options: ["Ask about the timing and details of the peels, explain that recently treated skin can be more fragile and reactive, and recommend either waiting an appropriate interval or considering a gentler hair removal method for that area", "Proceed with waxing immediately, since chemical peels and waxing have no relationship to one another", "Recommend the client schedule an even more intensive peel immediately before the waxing appointment", "Refuse to discuss the topic, since treatments performed in a different service category are never relevant to today's planning"], correct: 0, options_es: ["Preguntar sobre el momento y los detalles de los peelings, explicar que la piel recientemente tratada puede ser más frágil y reactiva, y recomendar esperar un intervalo apropiado o considerar un método de depilación más suave para esa área", "Proceder con la depilación con cera de inmediato, ya que los peelings químicos y la depilación con cera no tienen ninguna relación entre sí", "Recomendar que el cliente programe un peeling aún más intensivo inmediatamente antes de la cita de depilación", "Negarse a discutir el tema, ya que los tratamientos realizados en una categoría de servicio diferente nunca son relevantes para la planificación de hoy"], explanation: "Chemical peels can leave skin more fragile, sensitive, and prone to irritation or lifting for a period of time afterward. Waxing such skin increases the risk of significant irritation or damage. A thoughtful esthetician asks about the timing and nature of recent treatments — regardless of category — and recommends either an appropriate waiting period or a gentler hair removal method, prioritizing the client's skin health and safety over simply proceeding as scheduled." },
  { id: 475, question: "Which best describes appropriate draping, positioning, and modesty considerations for a hair removal service performed on an intimate or sensitive body area?", question_es: "¿Cuál describe mejor las consideraciones apropiadas de cobertura, posicionamiento y pudor para un servicio de depilación realizado en un área corporal íntima o sensible?", options: ["Using proper draping to expose only the area being treated, clearly explaining each step before performing it, maintaining professional conduct throughout, and being responsive to the client's comfort level at all times", "Exposing the client's entire body throughout the service regardless of which specific area is being treated", "Skipping any explanation of the process so the service can be completed as quickly as possible", "Disregarding the client's comfort level once the service has begun, since the plan cannot be changed at that point"], correct: 0, options_es: ["Usar una cobertura adecuada para exponer solo el área que se está tratando, explicar claramente cada paso antes de realizarlo, mantener una conducta profesional durante todo el proceso, y estar atento al nivel de comodidad del cliente en todo momento", "Exponer todo el cuerpo del cliente durante todo el servicio sin importar qué área específica se esté tratando", "Omitir cualquier explicación del proceso para que el servicio pueda completarse lo más rápido posible", "Ignorar el nivel de comodidad del cliente una vez que el servicio ha comenzado, ya que el plan no se puede cambiar en ese momento"], explanation: "Services performed on intimate or sensitive areas call for heightened attention to professionalism, modesty, and clear communication. Proper draping that exposes only the area being treated, explaining each step in advance, maintaining a professional and respectful demeanor, and remaining responsive to the client's comfort throughout the service all help the client feel safe, respected, and in control of their experience." },
]

let out = readFileSync(FILE, 'utf8')
out += HR.map(fmt).join('\n') + '\n'
writeFileSync(FILE, out, 'utf8')
console.log(`Appended ${HR.length} Hair Removal (ids ${HR[0].id}–${HR[HR.length-1].id})`)
